SELECT compound_structures.canonical_smiles, compound_records.compound_name AS substrate_compound_name, parent_cr.compound_name AS parent_compound_name, metabolism.met_conversion, metabolism.pathway_key, metabolism.organism, metabolism.enzyme_name FROM metabolism JOIN compound_records ON metabolism.substrate_record_id = compound_records.record_id JOIN compound_structures ON compound_records.molregno = compound_structures.molregno LEFT JOIN compound_records AS parent_cr ON metabolism.drug_record_id = parent_cr.record_id WHERE metabolism.enzyme_name = 'CYP2D6' ORDER BY compound_structures.canonical_smiles ASC, compound_records.compound_name ASC, parent_cr.compound_name ASC, metabolism.met_conversion ASC, metabolism.pathway_key ASC, metabolism.organism ASC, metabolism.enzyme_name ASC LIMIT 200
